160 |     /// @notice Allows members of the `WHITELISTED_ROLE` to borrow `amount` of PUSD against the deposited collateral
161 |     /// @dev Emits a {Borrow} event
162 |     /// @param amount The amount of PUSD to borrow
163 |     function borrow(uint256 amount) external onlyRole(WHITELISTED_ROLE) nonReentrant {
164 |         require(amount > 0, "invalid_amount");
165 | 
166 |         uint256 creditLimit = getCreditLimit(collateralAmount);
167 |         uint256 newDebtAmount = debtAmount + amount;
168 |         require(newDebtAmount <= creditLimit, "insufficient_credit");
169 | 
170 |         debtAmount = newDebtAmount;
171 |         stablecoin.mint(msg.sender, amount);
172 | 
173 |         emit Borrow(msg.sender, amount);
174 |     }
